    pub fn ecdsa_secp256r1_verify_signature(self: *BarretenbergApi, message: []const u8, public_key: AffineElement, r: []const u8, s: []const u8, v: u8) !types.EcdsaSecp256r1VerifySignatureResponse {
        const cmd = types.Command{ .ecdsa_secp256r1_verify_signature = types.EcdsaSecp256r1VerifySignature{ .type_name = "EcdsaSecp256r1VerifySignature", .message = message, .public_key = public_key, .r = r, .s = s, .v = v } };
