    pub fn shutdown(self: *BarretenbergApi) !void {
        const cmd = types.Command{ .shutdown = types.Shutdown{} };
        _ = try self.execute(cmd);
        try self.backend.destroy();
    }

    pub fn destroy(self: *BarretenbergApi) !void {
        try self.backend.destroy();
    }

    fn execute(self: *BarretenbergApi, command: types.Command) !types.Response {
        // Serialize command to msgpack
        var list = std.ArrayList(u8).init(self.allocator);
        defer list.deinit();
        try msgpack.pack(command, list.writer());

        // Call backend
        const response_bytes = try self.backend.call(list.items);
        defer self.allocator.free(response_bytes);

        // Deserialize response
        const response = try msgpack.unpack(types.Response, self.allocator, response_bytes);
        return response;
    }
};